-- What's new for the 2026-11-19 release (OPI staff feedback on Project Setup and
-- Closeout: assignments per estimate in packages, Job Schedule reference-only,
-- schedules per estimate, closeout against the estimates, pay-date reasons),
-- published when the migration runs (the deploy).
INSERT INTO release_notes (title, body, page, tour_key, capability, published_at, created_by)
SELECT * FROM (
  SELECT 'Assignments are per estimate, in packages' AS title, 'A package is one or more estimates that share dates (an add-on change order joins the original''s package, a change order with its own dates gets its own). Pick the PM per estimate or set one PM for all, a PM can be set before there are dates. Pick the crew per estimate once its package has dates, sorted by who''s free, with the offer status beside it. Overage days are now the project''s, only for running past the scheduled end without a change order. Same on Project Setup, the project''s Assignment tab and Ashley''s Tracker.' AS body, '#/setup' AS page, NULL AS tour_key, 'page.assignment' AS capability, NOW() - INTERVAL 0 SECOND AS published_at, 'release-1119' AS created_by
  UNION ALL SELECT 'The Job Schedule is for reference', 'The Job Schedule sheet no longer changes dates, crews or overage in the app. Where it says something different, the date range shows "Job Schedule says ..." with Use these to take its values in one click.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 1 SECOND, 'release-1119'
  UNION ALL SELECT 'Project Setup: the whole contract and every estimate', 'The header shows the contract (every accepted estimate) with pending change orders under it, and the comments fold into the header. Project estimate created lists every estimate on one line each. Open one to see how it ties to its PO (number, total, terms). First invoice sent lists each estimate''s first invoice with its expected date, and lets you say a change order needs no first invoice.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 2 SECOND, 'release-1119'
  UNION ALL SELECT 'Schedules follow each estimate', 'Invoices, crew pay and expenses are planned per estimate from its package''s dates. A new crew schedule pays first on the second payday after the PO, then every other Friday, and asks you to confirm the dates. Adding or removing a crew payment re-balances the other open payments so they still add up to the contract labor, and the section stays open.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 3 SECOND, 'release-1119'
  UNION ALL SELECT 'Project Closeout checks against the estimates', 'Finished jobs are judged against their estimates: contract labor and each expense item on the estimates, burned down by what was actually paid (older jobs no longer show $0). Close a money step as reviewed even when it''s short, or press Not ready to note what''s still open.', '#/closeout', NULL, 'page.assignment', NOW() - INTERVAL 4 SECOND, 'release-1119'
  UNION ALL SELECT 'A reason on each pay date', 'Invoice & Pay Dates has a Reason box on every line: type why an invoice is where it is and move on. It saves when you leave the box, with your name.', '#/pay-dates', NULL, 'page.assignment', NOW() - INTERVAL 5 SECOND, 'release-1119'
) d
WHERE NOT EXISTS (SELECT 1 FROM release_notes WHERE created_by = 'release-1119');
